                ${cur_frm.bg_hide_delta ? "" : `<div class="bg-group-delta${delta==0?" zero":""}"><span>${delta}%</span></div>`}
            </div>`;
}

function numberformat(x) {
    return Number.isFinite(x) ? x.toFixed(0).toString().replace(/\B(?=(\d{3})+(?!\d))/g, " ") : x;
}

