        } else {
            let new_doc = {
                doctype: "Project Budget",
                pb_project: project,
                pb_account: account,
            };
            return frappe.db.insert(new_doc);
        }
    }).then(doc => {
        let existRow = doc.project_budget_amount.find(row => row.pba_year == year && row.pba_month == month);
        if (!existRow) {
            let newRow = frappe.model.add_child(doc, "Project Budget Amount", "project_budget_amount");
            newRow.pba_year = year;
            newRow.pba_month = month;
            newRow.pba_expected = new_value;
        } else {
            existRow.pba_expected = new_value;
        }
        return frappe.call({
            method: 'frappe.client.save',
            args: { doc: doc }
        });
    }).then(result => {
        frappe.show_alert({
            message: __('Данные сохранены'),
