function update_rate_mandatory_fields(frm) {
	const grid = frm.fields_dict.custom_ts_details && frm.fields_dict.custom_ts_details.grid;
	if (!grid || !grid.grid_rows) {
		return;
	}
	const isTimeAndMaterials = frm.doc.custom_payment_scheme === "Время и затраты (T&M)";
	grid.grid_rows.forEach((row, index) => {
		if (!row.fields_dict) {
			return;
		}
		const rowData = frm.doc.custom_ts_details[index];
		const isVirtualWorker = !!(rowData && rowData.virtual_worker);
		if (row.fields_dict.pt_cost_level) {
			row.fields_dict.pt_cost_level.df.is_mandatory = isVirtualWorker;
			row.fields_dict.pt_cost_level.refresh();
		}
		if (row.fields_dict.pt_category) {
			row.fields_dict.pt_category.df.is_mandatory = isTimeAndMaterials;
			row.fields_dict.pt_category.refresh();
		}
	});
}

