async function calculate_levels(frm) {
	if (!frappe.meta.get_docfield('Project Team Details', 'base_cost_level')) {
		return;
	}
	if (!(await worker_doctype_exists())) {
		return;
	}

	const promises = frm.doc.custom_ts_details
		.filter(row => row.pt_participant)
		.map(row => calculate_row_level(frm, row));

	await Promise.all(promises);
	frm.refresh_field('custom_ts_details');
}

async function worker_doctype_exists() {
	try {
		return !!(await frappe.db.exists('DocType', 'Worker'));
	} catch (err) {
		return false;
	}
}

async function calculate_row_level(frm, row) {
	if (!row.pt_participant) return;

	try {
		const worker = await frappe.db.get_value('Worker',
			{ wuser: row.pt_participant },
			['name']
		);

		if (!worker?.message?.name) return;

		const workerDoc = await frappe.db.get_doc('Worker', worker.message.name);

		if (!workerDoc?.worker_level || workerDoc.worker_level.length === 0) return;

		const now = new Date();
		const validLevels = workerDoc.worker_level
			.filter(level => level.wl_valid_from && new Date(level.wl_valid_from) <= now)
			.sort((a, b) => new Date(b.wl_valid_from) - new Date(a.wl_valid_from));

		if (validLevels.length === 0) return;

		row.base_cost_level = validLevels[0].wl_cosl_level;

	} catch (err) {
		// Ошибки обрабатываются silently
		console.error(err);
	}
}

frappe.ui.form.on("Project", {
	validate(frm) {
		if (!frm.doc.custom_ts_details) {
			return;
		}
		if (!frappe.meta.get_docfield("Project Team Details", "virtual_worker")) {
			return;
		}

		const virtualParticipants = {};
		const errors = [];
		const hasWorker = !!frappe.meta.get_docfield("Project Team Details", "pt_worker");
		const hasApproval = !!frappe.meta.get_docfield("Project Team Details", "allow_approval");
		const hasPss = !!frappe.meta.get_docfield("Project Team Details", "pt_allow_pss");
		const hasLimitNotifications = !!frappe.meta.get_docfield(
			"Project Team Details",
			"notifications_on_limits"
		);

		frm.doc.custom_ts_details.forEach((row, index) => {
			const rowNum = index + 1;
			if (!row.virtual_worker) {
				return;
			}

			if (row.pt_participant_type) {
				row.pt_participant_type = null;
			}
			if (row.pt_participant) {
				row.pt_participant = null;
			}
			if (hasWorker && row.pt_worker) {
				row.pt_worker = null;
			}
			if (hasApproval && row.allow_approval) {
				row.allow_approval = 0;
			}
			if (hasPss && row.pt_allow_pss) {
				row.pt_allow_pss = 0;
			}
			if (hasLimitNotifications && row.notifications_on_limits) {
				row.notifications_on_limits = 0;
			}

			const virtualKey = row.pt_role + "_virtual";
			const existing = virtualParticipants[virtualKey];
			if (
				existing &&
				row.pt_valid_from &&
				row.pt_valid_for &&
				existing.pt_valid_from &&
				existing.pt_valid_for &&
				((row.pt_valid_from >= existing.pt_valid_from && row.pt_valid_from <= existing.pt_valid_for) ||
					(row.pt_valid_for >= existing.pt_valid_from && row.pt_valid_for <= existing.pt_valid_for))
			) {
				errors.push(
					__("Внимание! Виртуальный работник уже назначен на роль '{0}' в пересекающийся период (строки {1} и {2})", [
						row.pt_role,
						existing.idx,
						rowNum,
					])
				);
			}
			virtualParticipants[virtualKey] = {
				pt_valid_from: row.pt_valid_from,
				pt_valid_for: row.pt_valid_for,
				idx: rowNum,
			};
		});

		if (errors.length) {
			frappe.throw(errors.join("<br>"));
		}
	}
});

