// Demodev hotfix: glue forecast menu arrays so Include Risk Reserve survives PWA overwrite.
function dinext_glue_forecast_menus() {
	frappe.provide("dinext_projects.project_pl_forecast_menu");
	frappe.provide("dinext_projects.project_budget_forecast_menu");
	var pl = dinext_projects.project_pl_forecast_menu;
	var budget = dinext_projects.project_budget_forecast_menu;
	if (!Array.isArray(pl)) { pl = []; }
	if (Array.isArray(budget) && budget !== pl) {
		if (budget.length && !pl.length) { pl = budget; }
		else {
			budget.forEach(function (item) {
				if (item && pl.indexOf(item) === -1) { pl.push(item); }
			});
		}
	}
	dinext_projects.project_pl_forecast_menu = pl;
	dinext_projects.project_budget_forecast_menu = pl;
	return pl;
}
function dinext_refresh_pl_forecast_menu(frm) {
	dinext_glue_forecast_menus();
	var fn = dinext_projects.refresh_project_budget_forecast_dropdown || dinext_projects.refresh_pl_forecast_dropdown;
	if (typeof fn === "function") { fn(frm); }
}
